<?php
// CLI/Hostinger cron entry point. Example: php /home/USER/domains/DOMAIN/public_html/cron/scan-sources.php
require_once __DIR__.'/../config/app.php';
require_once __DIR__.'/../includes/ai_extractor.php';

if (PHP_SAPI !== 'cli' && (($_SERVER['HTTP_X_NAUKRISCAN_CRON'] ?? '') !== (getenv('NAUKRISCAN_CRON_TOKEN') ?: ''))) { http_response_code(403); exit('Forbidden'); }

function scanner_canonical_url(string $url): string { $p=parse_url($url); if(!$p || empty($p['host'])) return $url; $scheme=strtolower($p['scheme']??'https'); $host=strtolower($p['host']); $path=$p['path']??'/'; $query=$p['query']??''; parse_str($query,$q); foreach(['utm_source','utm_medium','utm_campaign','utm_term','utm_content','fbclid','gclid'] as $k) unset($q[$k]); $query=http_build_query($q); return $scheme.'://'.$host.rtrim($path,'/').($query?'?'.$query:''); }
function scanner_safe_url(string $url): bool { if(!filter_var($url,FILTER_VALIDATE_URL)) return false; $p=parse_url($url); if(!in_array(strtolower($p['scheme']??''),['http','https'],true)) return false; $host=$p['host']??''; if($host==='' || preg_match('/(^|\.)localhost$/i',$host) || filter_var($host,FILTER_VALIDATE_IP) && !filter_var($host,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE)) return false; return true; }
function scanner_fetch(string $url): array { if(!scanner_safe_url($url)) throw new RuntimeException('Unsafe or invalid URL.'); $ch=curl_init($url); curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>4,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_TIMEOUT=>35,CURLOPT_USERAGENT=>'NaukriScan/20 (+government-job-source-scanner)',CURLOPT_HTTPHEADER=>['Accept: text/html,application/xhtml+xml,application/pdf;q=0.9,*/*;q=0.5']]); $body=curl_exec($ch); $err=curl_error($ch); $status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE); $type=(string)curl_getinfo($ch,CURLINFO_CONTENT_TYPE); $final=(string)curl_getinfo($ch,CURLINFO_EFFECTIVE_URL); curl_close($ch); if($body===false||$err) throw new RuntimeException('Fetch failed: '.$err); if($status<200||$status>=400) throw new RuntimeException('HTTP '.$status); if(strlen($body)>8*1024*1024) throw new RuntimeException('Response exceeded 8 MB limit.'); return [$body,$status,$type,$final]; }
function scanner_links(string $html,string $base): array { $out=[]; libxml_use_internal_errors(true); $dom=new DOMDocument(); @$dom->loadHTML($html); foreach($dom->getElementsByTagName('a') as $a){$href=trim($a->getAttribute('href')); if($href==='')continue; $text=trim(preg_replace('/\s+/',' ',$a->textContent)); if(preg_match('~^(javascript:|mailto:|tel:)~i',$href))continue; $u=resolve_link($base,$href); if(!$u||!scanner_safe_url($u))continue; $path=strtolower(parse_url($u,PHP_URL_PATH)??''); $hay=strtolower($text.' '.$u); if(preg_match('/(recruit|career|vacan|advert|notic|job|result|apprent|engagement|selection|pdf)/i',$hay) || substr($path,-4)==='.pdf') $out[$u]=['url'=>$u,'title'=>$text]; } libxml_clear_errors(); return array_values($out); }
function resolve_link(string $base,string $href): ?string { if(preg_match('~^https?://~i',$href)) return $href; $bp=parse_url($base); if(!$bp||empty($bp['scheme'])||empty($bp['host'])) return null; if(substr($href,0,2)==='//' ) return $bp['scheme'].':'.$href; if(substr($href,0,1)==='/') return $bp['scheme'].'://'.$bp['host'].$href; $dir=rtrim(dirname($bp['path']??'/'),'/'); return $bp['scheme'].'://'.$bp['host'].($dir?'/'.$dir:'').'/'.ltrim($href,'./'); }
function scanner_text_from_html(string $html): string { $html=preg_replace('~<(script|style|noscript)[^>]*>.*?</\1>~is',' ',$html); $text=html_entity_decode(strip_tags($html),ENT_QUOTES|ENT_HTML5,'UTF-8'); return trim(preg_replace('/\s+/u',' ',$text)); }
function scanner_create_job(PDO $pdo,array $x,string $sourceUrl,int $adminId=0): int { $title=trim((string)($x['job_title']??'')); $org=trim((string)($x['organization']??'')); if($title===''||$org==='') return 0; $st=$pdo->prepare("SELECT id FROM jobs WHERE source_url=? LIMIT 1"); $st->execute([$sourceUrl]); if($id=$st->fetchColumn()) return (int)$id; $st=$pdo->prepare("SELECT id FROM jobs WHERE LOWER(organization)=LOWER(?) AND LOWER(job_title)=LOWER(?) AND status<>'archived' LIMIT 1"); $st->execute([$org,$title]); if($id=$st->fetchColumn()) return (int)$id; $uid='JOB-'.strtoupper(bin2hex(random_bytes(4))); $pdo->prepare("INSERT INTO jobs(job_uid,organization,department,job_title,short_description,job_type,location,state,district,vacancy_count,status,source_url,application_url,closing_date,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)")->execute([$uid,$org,(string)($x['department']??''),$title,'AI discovered from official government source',(string)($x['job_type']??''),(string)($x['location']??''),(string)($x['state']??''),(string)($x['district']??''),(int)($x['vacancy_count']??0),'pending_verification',$sourceUrl,(string)($x['official_application_url']??''),normalize_date($x['application_end']??null),$adminId?:null]); $jid=(int)$pdo->lastInsertId(); $pdo->prepare("INSERT INTO job_eligibility(job_id,min_age,max_age,education_required,experience_required,gender_requirement,nationality_requirement,domicile_requirement,category_rules,pwd_rules,other_conditions,age_relaxation_rules,allowed_categories,pwd_min_percentage,pwd_eligibility,ex_serviceman_rule,domicile_states,qualification_rules,minimum_experience_months,experience_notes,eligibility_review_notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)")->execute([$jid,$x['min_age']??null,$x['max_age']??null,$x['education_required']??'',$x['experience_required']??'',$x['gender_requirement']??'',$x['nationality_requirement']??'Indian',$x['domicile_requirement']??'',$x['category_rules']??'',$x['pwd_rules']??'',$x['other_conditions']??'',$x['age_relaxation_rules']??'',$x['allowed_categories']??'',$x['pwd_min_percentage']??null,$x['pwd_eligibility']??'',$x['ex_serviceman_rules']??'',$x['domicile_states']??'',$x['qualification_rules']??'',$x['minimum_experience_months']??null,$x['experience_notes']??'','AI discovered; human verification required before publication.']); $pdo->prepare("INSERT INTO job_dates(job_id,notification_date,application_start,application_end,fee_last_date,exam_date,admit_card_date,result_date) VALUES(?,?,?,?,?,?,?,?)")->execute([$jid,normalize_date($x['notification_date']??null),normalize_date($x['application_start']??null),normalize_date($x['application_end']??null),normalize_date($x['fee_last_date']??null),normalize_date($x['exam_date']??null),normalize_date($x['admit_card_date']??null),normalize_date($x['result_date']??null)]); return $jid; }
function normalize_date($v){$v=trim((string)$v); if($v==='')return null; $t=strtotime($v); return $t?date('Y-m-d',$t):null;}

$pdo=db(); $limit=20; $st=$pdo->prepare("SELECT * FROM job_sources WHERE active=1 AND (next_scan_at IS NULL OR next_scan_at<=NOW()) ORDER BY priority='high' DESC,priority='medium' DESC,last_scan_at IS NULL DESC,next_scan_at ASC LIMIT {$limit}"); $st->execute(); $sources=$st->fetchAll(); $summary=['sources'=>0,'documents'=>0,'jobs'=>0,'duplicates'=>0,'failed'=>0];
foreach($sources as $source){ $summary['sources']++; $started=date('Y-m-d H:i:s'); $pdo->prepare("INSERT INTO source_scan_logs(source_id,started_at,status) VALUES(?,?,'running')")->execute([$source['id'],$started]); $logId=(int)$pdo->lastInsertId(); $found=0;$new=0;$extracted=0;$created=0;$dupes=0;$failed=0;$errors=[]; try { [$body,$http,$ctype,$final]=scanner_fetch($source['source_url']); $links=[]; $isPdf=strpos(strtolower($ctype),'pdf')!==false||substr(strtolower(parse_url($final,PHP_URL_PATH)??''),-4)==='.pdf'; if($isPdf) $links=[['url'=>$final,'title'=>$source['source_name']]]; else { $links=scanner_links($body,$final); $links=array_slice($links,0,20); } $found=count($links); foreach($links as $link){ try { [$content,$status,$type,$effective]=scanner_fetch($link['url']); $canonical=scanner_canonical_url($effective); $hash=hash('sha256',$content); $st=$pdo->prepare('SELECT id FROM source_documents WHERE sha256=? LIMIT 1'); $st->execute([$hash]); if($docId=$st->fetchColumn()){ $dupes++; $pdo->prepare('UPDATE source_documents SET last_seen_at=NOW(),http_status=?,mime_type=? WHERE id=?')->execute([$status,$type,$docId]); continue; } $path='storage/ai/source-documents/'.(int)$source['id']; $full=__DIR__.'/../'.$path; if(!is_dir($full))mkdir($full,0750,true); $ext=strpos(strtolower($type),'pdf')!==false||substr(strtolower(parse_url($effective,PHP_URL_PATH)??''),-4)==='.pdf'?'pdf':'html'; $file=$path.'/'.hash('sha256',$canonical).'.'.$ext; file_put_contents(__DIR__.'/../'.$file,$content,LOCK_EX); $pdo->prepare('INSERT INTO source_documents(source_id,source_url,canonical_url,sha256,mime_type,http_status,content_title,content_path,extraction_status) VALUES(?,?,?,?,?,?,?,?,\'pending\')')->execute([$source['id'],$link['url'],$canonical,$hash,$type,$status,$link['title']??'', $file]); $docId=(int)$pdo->lastInsertId(); $new++; $text=''; if($ext==='pdf'){ try{$text=extract_pdf_text_local(__DIR__.'/../'.$file);}catch(Throwable $e){throw new RuntimeException('PDF text extraction: '.$e->getMessage());} } else $text=scanner_text_from_html($content); if(strlen($text)<300) throw new RuntimeException('Insufficient readable content.'); $x=ai_extract_notification(substr($text,0,120000)); $extracted++; $confidence=(float)($x['confidence']??0); $statusLog=$confidence>=85?'ready':'review'; $pdo->prepare("INSERT INTO ai_extraction_logs(job_id,admin_id,provider,model,source_type,source_reference,source_text,extracted_json,status,source_sha256,prompt_version) VALUES(NULL,NULL,?,?,?,?,?,?,?,?,'v20')")->execute([AI_PROVIDER,AI_MODEL,$ext,$file,$text,json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),$statusLog,$hash]); $aiLog=(int)$pdo->lastInsertId(); $jobId=0; if($confidence>=85 && !empty($x['organization']) && !empty($x['job_title'])) $jobId=scanner_create_job($pdo,$x,$effective); $pdo->prepare('UPDATE source_documents SET extraction_status=?,extraction_log_id=?,job_id=? WHERE id=?')->execute([$jobId?'job_created':$statusLog,$aiLog,$jobId?:null,$docId]); if($jobId){$created++; $pdo->prepare('UPDATE ai_extraction_logs SET job_id=? WHERE id=?')->execute([$jobId,$aiLog]); audit_admin('AI_DISCOVER','jobs',$jobId,null,json_encode(['source_id'=>$source['id'],'confidence'=>$confidence]));} } catch(Throwable $e){$failed++; if(!empty($docId)) { try{$pdo->prepare("UPDATE source_documents SET extraction_status='failed',last_seen_at=NOW() WHERE id=?")->execute([(int)$docId]);}catch(Throwable $ignored){} } $errors[]=$link['url'].' — '.$e->getMessage();} } $summary['documents']+=$new;$summary['jobs']+=$created;$summary['duplicates']+=$dupes;$summary['failed']+=$failed; $status=$failed&&$created===0?'failed':'success'; $pdo->prepare("UPDATE source_scan_logs SET finished_at=NOW(),status=?,found_links=?,new_documents=?,extracted_count=?,created_jobs=?,duplicate_count=?,failed_count=?,error_message=?,details_json=? WHERE id=?")->execute([$status,$found,$new,$extracted,$created,$dupes,$failed,$errors?implode("\n",array_slice($errors,0,20)):null,json_encode(['errors'=>$errors],JSON_UNESCAPED_UNICODE),$logId]); $pdo->prepare("UPDATE job_sources SET last_scan_at=NOW(),next_scan_at=DATE_ADD(NOW(),INTERVAL scan_frequency_minutes MINUTE),last_status=?,last_error=?,last_found_count=?,last_new_count=?,updated_at=NOW() WHERE id=?")->execute([$status,$errors?implode("\n",array_slice($errors,0,5)):null,$found,$new,$source['id']]); } catch(Throwable $e){$summary['failed']++; $pdo->prepare("UPDATE source_scan_logs SET finished_at=NOW(),status='failed',error_message=? WHERE id=?")->execute([$e->getMessage(),$logId]); $pdo->prepare("UPDATE job_sources SET last_scan_at=NOW(),next_scan_at=DATE_ADD(NOW(),INTERVAL scan_frequency_minutes MINUTE),last_status='failed',last_error=?,updated_at=NOW() WHERE id=?")->execute([$e->getMessage(),$source['id']]); } }
if(PHP_SAPI==='cli') echo json_encode(['ok'=>true,'summary'=>$summary],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL; else header('Content-Type: application/json'); echo json_encode(['ok'=>true,'summary'=>$summary],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE);
